const input = $input.first().json ?? {};

function optionalPositiveInteger(value) {
  if (
    value === null ||
    value === undefined ||
    value === ''
  ) {
    return null;
  }

  const number = Number(value);

  return Number.isInteger(number) && number > 0
    ? number
    : null;
}

function parseObject(value) {
  if (
    value &&
    typeof value === 'object' &&
    !Array.isArray(value)
  ) {
    return value;
  }

  if (typeof value === 'string') {
    try {
      const parsed = JSON.parse(value);

      return (
        parsed &&
        typeof parsed === 'object' &&
        !Array.isArray(parsed)
      )
        ? parsed
        : {};
    } catch {
      return {};
    }
  }

  return {};
}

function parseBoolean(value) {
  if (value === true) {
    return true;
  }

  if (value === false) {
    return false;
  }

  const normalized = String(value ?? '')
    .trim()
    .toLowerCase();

  return (
    normalized === 'true' ||
    normalized === '1' ||
    normalized === 'yes'
  );
}

/*
 * Basic request fields
 */
const sessionId =
  String(input.session_id ?? '').trim() ||
  'missing-session';

const message =
  String(input.message ?? '').trim();

const usecaseId =
  optionalPositiveInteger(input.usecase_id);

const userId =
  optionalPositiveInteger(input.user_id);

const userMappingId =
  optionalPositiveInteger(input.user_mapping_id);

const usecaseName =
  String(input.usecase_name ?? '').trim() ||
  null;

/*
 * Read deterministic application context.
 *
 * The scope may exist:
 * 1. directly on the workflow input;
 * 2. inside context;
 * 3. inside context.app_context.
 */
const originalContext =
  parseObject(input.context);

const appContext =
  parseObject(originalContext.app_context);

const allUsersSelected =
  parseBoolean(input.all_users_selected) ||
  parseBoolean(originalContext.all_users_selected) ||
  parseBoolean(appContext.all_users_selected);

const requestedScope =
  String(
    input.analysis_scope ??
    originalContext.analysis_scope ??
    appContext.analysis_scope ??
    ''
  )
    .trim()
    .toLowerCase();

/*
 * Scope is deterministic.
 *
 * usecase:
 *   analyze the selected experiment across all users.
 *
 * participant:
 *   analyze one selected participant.
 */
const analysisScope =
  requestedScope === 'usecase' ||
  requestedScope === 'participant'
    ? requestedScope
    : allUsersSelected
      ? 'usecase'
      : 'participant';

/*
 * In use-case scope, ignore any accidental participant ID.
 * This prevents an All Users request from being narrowed to one user.
 */
const normalizedUserId =
  analysisScope === 'participant'
    ? userId
    : null;

/*
 * Preserve the original context while making the resolved
 * scope easy for downstream nodes to access.
 */
const normalizedContext = {
  ...originalContext,

  analysis_scope:
    analysisScope,

  all_users_selected:
    allUsersSelected,

  app_context: {
    ...appContext,

    selected_usecase_id:
      appContext.selected_usecase_id ??
      usecaseId,

    selected_usecase_name:
      appContext.selected_usecase_name ??
      usecaseName,

    selected_user_id:
      analysisScope === 'participant'
        ? (
            appContext.selected_user_id ??
            normalizedUserId
          )
        : null,

    selected_user_mapping_id:
      appContext.selected_user_mapping_id ??
      userMappingId,

    analysis_scope:
      analysisScope,

    all_users_selected:
      allUsersSelected
  }
};

/*
 * Validate according to the resolved scope.
 */
const warnings = [];

if (!message) {
  warnings.push(
    'No participant or experiment analysis request was provided.'
  );
}

if (!usecaseId) {
  warnings.push(
    'No valid use case ID was provided.'
  );
}

if (
  analysisScope === 'participant' &&
  !normalizedUserId
) {
  warnings.push(
    'No valid participant user ID was provided for participant-level analysis.'
  );
}

/*
 * A user ID is required only in participant mode.
 * It is intentionally optional in use-case mode.
 */
const valid =
  Boolean(
    message &&
    usecaseId &&
    (
      analysisScope === 'usecase' ||
      normalizedUserId
    )
  );

return [{
  json: {
    valid,

    session_id:
      sessionId,

    message,

    usecase_id:
      usecaseId,

    usecase_name:
      usecaseName,

    user_id:
      normalizedUserId,

    user_mapping_id:
      userMappingId,

    analysis_scope:
      analysisScope,

    all_users_selected:
      allUsersSelected,

    context:
      normalizedContext,

    input_warnings:
      warnings
  }
}];

const input = $input.first().json ?? {};

return [{
  json: {
    expert: 'participant_data',
    success: false,

    reply:
      'The Participant Data Expert needs a participant, a selected use case, and a request before it can perform an analysis.',

    session_id:
      input.session_id ?? null,

    citations: [],

    warnings:
      input.input_warnings ?? [],

    proposals: [],
    recommended_actions: [],

    participant_assessment: null,
    findings: []
  }
}];

const row = $input.first().json ?? {};

const request =
  $('Normalize Participant Request').first().json ?? {};

function parseJsonValue(value, fallback) {
  if (
    value === null ||
    value === undefined ||
    value === ''
  ) {
    return fallback;
  }

  if (typeof value === 'object') {
    return value;
  }

  if (typeof value === 'string') {
    try {
      return JSON.parse(value);
    } catch {
      return fallback;
    }
  }

  return fallback;
}

function objectValue(value) {
  const parsed =
    parseJsonValue(value, {});

  return (
    parsed &&
    typeof parsed === 'object' &&
    !Array.isArray(parsed)
  )
    ? parsed
    : {};
}

function nullableObject(value) {
  const parsed =
    parseJsonValue(value, null);

  return (
    parsed &&
    typeof parsed === 'object' &&
    !Array.isArray(parsed)
  )
    ? parsed
    : null;
}

function arrayValue(value) {
  const parsed =
    parseJsonValue(value, []);

  return Array.isArray(parsed)
    ? parsed
    : [];
}

function numberOrNull(value) {
  if (
    value === null ||
    value === undefined ||
    value === ''
  ) {
    return null;
  }

  const number =
    Number(value);

  return Number.isFinite(number)
    ? number
    : null;
}

const participantStats =
  objectValue(
    row.participant_stats
  );

const recent7dStats =
  objectValue(
    row.recent_7d_stats
  );

const feedbackSummary =
  objectValue(
    row.feedback_summary
  );

const cohortSummary =
  objectValue(
    row.cohort_summary
  );

const globalActiveAssignment =
  nullableObject(
    row.global_active_assignment
  );

const assignmentHistory =
  arrayValue(
    row.assignment_history
  );

const mappingUsage =
  arrayValue(
    row.mapping_usage
  );

const warnings = [
  ...(Array.isArray(request.input_warnings)
    ? request.input_warnings
    : [])
];

const resolvedUserId =
  numberOrNull(
    row.user_id ??
    request.user_id
  );

const resolvedUsecaseId =
  numberOrNull(
    row.usecase_id ??
    request.usecase_id
  );

if (resolvedUserId === null) {
  warnings.push(
    `Participant ${request.user_id ?? 'unknown'} was not found.`
  );
}

if (resolvedUsecaseId === null) {
  warnings.push(
    `Use case ${request.usecase_id ?? 'unknown'} was not found.`
  );
}

const totalReadings =
  Number(
    participantStats.total_readings ?? 0
  );

const activeDays =
  Number(
    participantStats.active_days ?? 0
  );

const alertRecords =
  Number(
    feedbackSummary.alert_records ?? 0
  );

if (totalReadings === 0) {
  warnings.push(
    'No participant sensor readings were found for the selected use case during the last 30 days.'
  );
} else if (
  totalReadings < 20 ||
  activeDays < 3
) {
  warnings.push(
    'The recent participant dataset is limited. Personalization conclusions should be treated as tentative.'
  );
}

if (alertRecords === 0) {
  warnings.push(
    'No linked Alert records were found, so recent feedback burden cannot be estimated reliably.'
  );
}

if (!globalActiveAssignment) {
  warnings.push(
    'The participant does not currently have an active mapping assignment.'
  );
} else {
  const activeMappingId =
    numberOrNull(
      globalActiveAssignment?.mapping_id ??
      globalActiveAssignment?.mapping?.id
    );

  const activeMappingUsecaseId =
    numberOrNull(
      globalActiveAssignment?.mapping?.usecase_id
    );

  const activeMappingUsecaseName =
    globalActiveAssignment?.mapping?.usecase_name ??
    null;

  if (activeMappingUsecaseId === null) {
    warnings.push(
      `The participant's globally active mapping ` +
      `${activeMappingId ?? 'unknown'} does not have an associated use case.`
    );
  } else if (
    resolvedUsecaseId !== null &&
    activeMappingUsecaseId !== resolvedUsecaseId
  ) {
    warnings.push(
      `The participant's globally active mapping belongs to use case ` +
      `${activeMappingUsecaseName ?? activeMappingUsecaseId}, ` +
      `not the selected use case.`
    );
  }

  const selectedMappingId =
    numberOrNull(
      request.user_mapping_id
    );

  if (
    selectedMappingId !== null &&
    activeMappingId !== null &&
    activeMappingId !== selectedMappingId
  ) {
    warnings.push(
      `The selected mapping ID ${selectedMappingId} does not match ` +
      `the participant's current active mapping ID ${activeMappingId}.`
    );
  }
}

if (assignmentHistory.length === 0) {
  warnings.push(
    'No mapping-assignment history was found for this participant and use case.'
  );
}

return [{
  json: {
    session_id:
      request.session_id ?? null,

    message:
      request.message ?? '',

    user_id:
      resolvedUserId,

    participant_name:
      [row.fname, row.lname]
        .filter(Boolean)
        .join(' ')
        .trim() || null,

    last_request_at:
      row.lastrequest ?? null,

    usecase_id:
      resolvedUsecaseId,

    usecase_name:
      row.usecase_name ??
      request.usecase_name ??
      null,

    usecase_description:
      row.usecase_description ?? null,

    selected_user_mapping_id:
      numberOrNull(
        request.user_mapping_id
      ),

    context:
      request.context ?? {},

    participant_stats:
      participantStats,

    recent_7d_stats:
      recent7dStats,

    feedback_summary:
      feedbackSummary,

    cohort_summary:
      cohortSummary,

    global_active_assignment:
      globalActiveAssignment,

    assignment_history_count:
      Number(
        row.assignment_history_count ??
        assignmentHistory.length
      ),

    assignment_history:
      assignmentHistory,

    mapping_usage:
      mappingUsage,

    context_warnings: [
      ...new Set(warnings)
    ]
  }
}];

const raw =
  $input.first().json ?? {};

const context =
  $('Package Participant Context').first().json ?? {};

function parseJsonValue(value, fallback) {
  if (
    value === null ||
    value === undefined ||
    value === ''
  ) {
    return fallback;
  }

  if (typeof value === 'object') {
    return value;
  }

  if (typeof value === 'string') {
    try {
      return JSON.parse(value);
    } catch {
      return fallback;
    }
  }

  return fallback;
}

function parseResponse(value) {
  if (
    value &&
    typeof value === 'object' &&
    !Array.isArray(value)
  ) {
    return value;
  }

  let text =
    String(value ?? '').trim();

  text = text
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();

  try {
    return JSON.parse(text);
  } catch {
    return {
      reply: text,

      warnings: [
        'The Participant Data Expert did not return valid structured JSON.'
      ],

      participant_assessment: null,
      findings: [],
      recommended_actions: []
    };
  }
}

function arrayValue(value) {
  const parsed =
    parseJsonValue(value, []);

  return Array.isArray(parsed)
    ? parsed
    : [];
}

function objectValue(value) {
  const parsed =
    parseJsonValue(value, {});

  return (
    parsed &&
    typeof parsed === 'object' &&
    !Array.isArray(parsed)
  )
    ? parsed
    : {};
}

function nullableObject(value) {
  const parsed =
    parseJsonValue(value, null);

  return (
    parsed &&
    typeof parsed === 'object' &&
    !Array.isArray(parsed)
  )
    ? parsed
    : null;
}

function stringArray(value) {
  return arrayValue(value)
    .filter(
      item =>
        item !== null &&
        item !== undefined &&
        String(item).trim() !== ''
    )
    .map(item =>
      String(item).trim()
    );
}

function numberOrNull(value) {
  if (
    value === null ||
    value === undefined ||
    value === ''
  ) {
    return null;
  }

  const number =
    Number(value);

  return Number.isFinite(number)
    ? number
    : null;
}

/**
 * Parse model output.
 */
const candidate =
  raw.text ??
  raw.output ??
  raw.response ??
  raw.answer ??
  raw.result ??
  raw.reply ??
  raw;

const parsed =
  parseResponse(candidate);

/**
 * Read deterministic database context.
 */
const participantStats =
  objectValue(
    context.participant_stats
  );

const recent7dStats =
  objectValue(
    context.recent_7d_stats
  );

const feedbackSummary =
  objectValue(
    context.feedback_summary
  );

const cohortSummary =
  objectValue(
    context.cohort_summary
  );

const assignmentHistory =
  arrayValue(
    context.assignment_history
  );

const mappingUsage =
  arrayValue(
    context.mapping_usage
  );

const globalAssignment =
  nullableObject(
    context.global_active_assignment
  );

const userId =
  numberOrNull(
    context.user_id
  );

const selectedUsecaseId =
  numberOrNull(
    context.usecase_id
  );

const totalReadings =
  Number(
    participantStats.total_readings ?? 0
  );

const alertRecords =
  Number(
    feedbackSummary.alert_records ?? 0
  );

const feedbackEvents =
  Number(
    feedbackSummary.feedback_events ?? 0
  );

/**
 * Selected-use-case assignment evidence.
 */
const selectedUsecaseAssignmentIds = [
  ...new Set(
    assignmentHistory
      .map(item =>
        numberOrNull(
          item?.assignment_id
        )
      )
      .filter(id => id !== null)
  )
];

const selectedUsecaseMappingIds = [
  ...new Set([
    ...assignmentHistory
      .map(item =>
        numberOrNull(
          item?.mapping_id ??
          item?.mapping?.id
        )
      )
      .filter(id => id !== null),

    ...mappingUsage
      .map(item =>
        numberOrNull(
          item?.mapping_id ??
          item?.mapping?.id
        )
      )
      .filter(id => id !== null)
  ])
];

/**
 * Global active assignment evidence.
 */
const globalAssignmentId =
  numberOrNull(
    globalAssignment?.assignment_id
  );

const globalMappingId =
  numberOrNull(
    globalAssignment?.mapping_id ??
    globalAssignment?.mapping?.id
  );

const globalMappingUsecaseId =
  numberOrNull(
    globalAssignment?.mapping?.usecase_id
  );

const globalMappingUsecaseName =
  globalAssignment?.mapping?.usecase_name ??
  null;

/**
 * Construct deterministic database citations.
 */
const citations = [];

if (totalReadings > 0) {
  citations.push({
    type: 'database',
    source: 'SensorData',
    scope:
      'selected_participant_usecase',

    user_id:
      userId,

    usecase_id:
      selectedUsecaseId,

    window_days:
      Number(
        participantStats.window_days ?? 30
      ),

    total_readings:
      totalReadings,

    expert:
      'participant_data'
  });
}

if (alertRecords > 0) {
  citations.push({
    type: 'database',
    source: 'Alert',
    scope:
      'selected_participant_usecase',

    user_id:
      userId,

    usecase_id:
      selectedUsecaseId,

    window_days:
      30,

    alert_records:
      alertRecords,

    feedback_events:
      feedbackEvents,

    expert:
      'participant_data'
  });
}

if (
  selectedUsecaseAssignmentIds.length > 0
) {
  citations.push({
    type: 'database',
    source: 'User_UC_Mappings',
    scope:
      'selected_usecase_history',

    user_id:
      userId,

    usecase_id:
      selectedUsecaseId,

    assignment_ids:
      selectedUsecaseAssignmentIds,

    expert:
      'participant_data'
  });
}

if (
  selectedUsecaseMappingIds.length > 0
) {
  citations.push({
    type: 'database',
    source: 'feedback_config_rules',
    scope:
      'selected_usecase_context',

    record_ids:
      selectedUsecaseMappingIds,

    usecase_id:
      selectedUsecaseId,

    expert:
      'participant_data'
  });
}

if (
  globalAssignmentId !== null ||
  globalMappingId !== null
) {
  citations.push({
    type: 'database',
    source: 'User_UC_Mappings',
    scope:
      'global_active_assignment',

    assignment_id:
      globalAssignmentId,

    user_id:
      userId,

    mapping_id:
      globalMappingId,

    mapping_usecase_id:
      globalMappingUsecaseId,

    mapping_usecase_name:
      globalMappingUsecaseName,

    expert:
      'participant_data'
  });
}

if (
  globalMappingId !== null &&
  !selectedUsecaseMappingIds.includes(
    globalMappingId
  )
) {
  citations.push({
    type: 'database',
    source: 'feedback_config_rules',
    scope:
      'global_active_mapping',

    record_ids: [
      globalMappingId
    ],

    usecase_id:
      globalMappingUsecaseId,

    usecase_name:
      globalMappingUsecaseName,

    expert:
      'participant_data'
  });
}

/**
 * Normalize participant assessment.
 */
const assessmentRaw =
  objectValue(
    parsed.participant_assessment
  );

const allowedDataSufficiency =
  new Set([
    'insufficient',
    'limited',
    'adequate'
  ]);

const allowedPersonalizationSignals =
  new Set([
    'insufficient_data',
    'no_clear_signal',
    'consider_review'
  ]);

const allowedBurdenSignals =
  new Set([
    'unknown',
    'no_clear_signal',
    'consider_review'
  ]);

const participantAssessment = {
  data_sufficiency:
    allowedDataSufficiency.has(
      assessmentRaw.data_sufficiency
    )
      ? assessmentRaw.data_sufficiency
      : (
          totalReadings === 0
            ? 'insufficient'
            : 'limited'
        ),

  personalization_signal:
    allowedPersonalizationSignals.has(
      assessmentRaw.personalization_signal
    )
      ? assessmentRaw.personalization_signal
      : (
          totalReadings === 0
            ? 'insufficient_data'
            : 'no_clear_signal'
        ),

  feedback_burden_signal:
    allowedBurdenSignals.has(
      assessmentRaw.feedback_burden_signal
    )
      ? assessmentRaw.feedback_burden_signal
      : (
          alertRecords === 0
            ? 'unknown'
            : 'no_clear_signal'
        ),

  rationale:
    stringArray(
      assessmentRaw.rationale
    )
};

/**
 * Validate evidence references.
 */
const allowedEvidencePrefixes = [
  'participant_stats',
  'recent_7d_stats',
  'feedback_summary',
  'cohort_summary',
  'global_active_assignment',
  'assignment_history',
  'mapping_usage'
];

function normalizeEvidenceReference(value) {
  let reference =
    String(value ?? '').trim();

  if (!reference) {
    return null;
  }

  reference = reference
    .replace(
      /^recent_feedback_summary\./,
      'feedback_summary.'
    )
    .replace(
      /^current_globally_active_assignment\./,
      'global_active_assignment.'
    )
    .replace(
      /^current_global_assignment\./,
      'global_active_assignment.'
    );

  const valid =
    allowedEvidencePrefixes.some(
      prefix =>
        reference === prefix ||
        reference.startsWith(
          `${prefix}.`
        ) ||
        reference.startsWith(
          `${prefix}[`
        )
    );

  return valid
    ? reference
    : null;
}

let droppedEvidenceReferenceCount = 0;

const findings =
  arrayValue(
    parsed.findings
  )
    .slice(0, 8)
    .filter(
      finding =>
        finding &&
        typeof finding === 'object' &&
        !Array.isArray(finding)
    )
    .map((finding, index) => {
      const originalEvidenceRefs =
        stringArray(
          finding.evidence_refs
        );

      const normalizedEvidenceRefs = [
        ...new Set(
          originalEvidenceRefs
            .map(
              normalizeEvidenceReference
            )
            .filter(Boolean)
        )
      ];

      droppedEvidenceReferenceCount +=
        originalEvidenceRefs.length -
        normalizedEvidenceRefs.length;

      const requestedConfidence =
        String(
          finding.confidence ?? ''
        ).trim();

      const confidence =
        ['low', 'moderate', 'high']
          .includes(requestedConfidence)
            ? requestedConfidence
            : 'low';

      return {
        finding_id:
          `f${index + 1}`,

        category:
          String(
            finding.category ??
            'data_coverage'
          ).trim(),

        statement:
          String(
            finding.statement ?? ''
          ).trim(),

        evidence_refs:
          normalizedEvidenceRefs,

        confidence:
          normalizedEvidenceRefs.length > 0
            ? confidence
            : 'low'
      };
    })
    .filter(
      finding =>
        finding.statement
    );

/**
 * Normalize recommended actions.
 */
const allowedActions =
  new Set([
    'collect_more_data',
    'review_personalization',
    'review_feedback_burden',
    'compare_mapping_options'
  ]);

let recommendedActions =
  arrayValue(
    parsed.recommended_actions
  )
    .filter(
      action =>
        action &&
        typeof action === 'object' &&
        !Array.isArray(action)
    )
    .map(action => ({
      action:
        allowedActions.has(
          action.action
        )
          ? action.action
          : 'collect_more_data',

      label:
        String(
          action.label ??
          'Review participant data'
        ).trim(),

      reason:
        String(
          action.reason ?? ''
        ).trim()
    }));

if (
  recommendedActions.length === 0
) {
  recommendedActions = [
    totalReadings === 0
      ? {
          action:
            'collect_more_data',

          label:
            'Collect more participant data',

          reason:
            'No recent participant readings were available for a grounded personalization assessment.'
        }
      : {
          action:
            'review_personalization',

          label:
            'Review personalization evidence',

          reason:
            'Review the participant summary before deciding whether a custom mapping is appropriate.'
        }
  ];
}

/**
 * Combine warnings.
 */
const warnings = [
  ...new Set([
    ...stringArray(
      context.context_warnings
    ),
    ...stringArray(
      parsed.warnings
    )
  ])
];

if (
  droppedEvidenceReferenceCount > 0
) {
  warnings.push(
    `${droppedEvidenceReferenceCount} unsupported finding evidence reference` +
    `${droppedEvidenceReferenceCount === 1 ? ' was' : 's were'} removed.`
  );
}

/**
 * Construct the final reply.
 */
let reply =
  String(
    parsed.reply ??
    parsed.answer ??
    parsed.message ??
    ''
  ).trim();

const isPlaceholderReply =
  /a grounded participant summary written for the researcher/i
    .test(reply) ||
  /explicitly state that the analysis was read-only/i
    .test(reply) ||
  /write an actual concise summary/i
    .test(reply) ||
  /actual participant-specific summary/i
    .test(reply);

if (
  !reply ||
  isPlaceholderReply
) {
  const participantLabel =
    context.participant_name
      ? `${context.participant_name} (participant ${userId})`
      : `participant ${userId ?? 'unknown'}`;

  const usecaseLabel =
    context.usecase_name ??
    `use case ${selectedUsecaseId ?? 'unknown'}`;

  if (totalReadings === 0) {
    reply =
      `No recent ${usecaseLabel} sensor readings were found for ` +
      `${participantLabel} during the 30-day analysis window. ` +
      'There is not enough evidence to assess personalization needs or recent feedback burden.';
  } else {
    reply =
      `${participantLabel} has ${totalReadings} recorded sensor readings ` +
      `for ${usecaseLabel} during the 30-day analysis window. ` +
      'The available evidence should be reviewed before deciding whether personalization is appropriate.';
  }

  if (
    globalMappingId !== null &&
    globalMappingUsecaseId === null
  ) {
    reply +=
      ` The participant's globally active mapping ${globalMappingId} ` +
      'does not have an associated use case.';
  } else if (
    globalMappingId !== null &&
    globalMappingUsecaseId !== null &&
    selectedUsecaseId !== null &&
    globalMappingUsecaseId !==
      selectedUsecaseId
  ) {
    reply +=
      ` The participant's globally active mapping ${globalMappingId} belongs to ` +
      `${globalMappingUsecaseName ?? `use case ${globalMappingUsecaseId}`}, ` +
      `not ${usecaseLabel}.`;
  }
}

/**
 * Guarantee the read-only statement.
 */
const statesReadOnly =
  /nothing was saved|no records were changed|nothing was assigned|read-only/i
    .test(reply);

if (!statesReadOnly) {
  reply +=
    '\n\nThis was a read-only analysis. ' +
    'No records were changed and no mapping was assigned.';
}

const success =
  Boolean(
    userId !== null &&
    selectedUsecaseId !== null
  );

return [{
  json: {
    expert:
      'participant_data',

    success,

    reply,

    session_id:
      context.session_id ?? null,

    citations,

    warnings,

    proposals: [],

    recommended_actions:
      recommendedActions,

    participant_assessment:
      participantAssessment,

    findings
  }
}];

const row =
  $input.first()?.json ?? {};

function integerValue(value) {
  const number =
    Number(value);

  return Number.isFinite(number)
    ? Math.trunc(number)
    : 0;
}

function numericValue(value) {
  if (
    value === null ||
    value === undefined ||
    value === ''
  ) {
    return null;
  }

  const number =
    Number(value);

  return Number.isFinite(number)
    ? number
    : null;
}

function parseArray(value) {
  if (Array.isArray(value)) {
    return value;
  }

  if (typeof value === 'string') {
    try {
      const parsed =
        JSON.parse(value);

      return Array.isArray(parsed)
        ? parsed
        : [];
    } catch {
      return [];
    }
  }

  return [];
}

function formatRange(
  minimum,
  maximum,
  suffix = ''
) {
  const min =
    numericValue(minimum);

  const max =
    numericValue(maximum);

  if (
    min === null &&
    max === null
  ) {
    return 'not specified';
  }

  if (
    min !== null &&
    max !== null &&
    min === max
  ) {
    return `${min}${suffix}`;
  }

  if (
    min !== null &&
    max !== null
  ) {
    return `${min}â€“${max}${suffix}`;
  }

  if (min !== null) {
    return `from ${min}${suffix}`;
  }

  return `up to ${max}${suffix}`;
}

function plural(
  amount,
  singular,
  pluralForm
) {
  return amount === 1
    ? singular
    : pluralForm;
}

const usecaseId =
  integerValue(
    row.usecase_id
  );

const usecaseName =
  String(
    row.usecase_name ?? ''
  ).trim();

const description =
  String(
    row.usecase_description ?? ''
  ).trim();

const periodDays =
  integerValue(
    row.period_days
  ) || 30;

const assignedParticipants =
  integerValue(
    row.assigned_participant_count
  );

const participantsWithReadings =
  integerValue(
    row.participants_with_readings
  );

const totalReadings =
  integerValue(
    row.total_readings
  );

const minimumValue =
  numericValue(
    row.min_sensor_value
  );

const maximumValue =
  numericValue(
    row.max_sensor_value
  );

const averageValue =
  numericValue(
    row.avg_sensor_value
  );

const feedbackEvents =
  integerValue(
    row.feedback_event_count
  );

const participantsWithFeedback =
  integerValue(
    row.participants_with_feedback
  );

const activeMappingCount =
  integerValue(
    row.active_mapping_count
  );

const mappings =
  parseArray(
    row.active_mappings
  );



const warnings = [];

if (!usecaseName) {
  warnings.push(
    `No use case record was found for usecase_id ${usecaseId}.`
  );
}

if (totalReadings === 0) {
  warnings.push(
    `No sensor readings were found for the selected use case during the last ${periodDays} days.`
  );
}

if (activeMappingCount === 0) {
  warnings.push(
    'No active mappings were found for the selected use case.'
  );
}

/*
 * Build one concise mapping bullet.
 */
const mappingDescriptions =
  mappings.map(mapping => {
    const mappingId =
      integerValue(
        mapping.mapping_id
      );

    const assignedUsers =
      integerValue(
        mapping.assigned_user_count
      );

    const valueRange =
      formatRange(
        mapping.minvalue,
        mapping.maxvalue,
        ' BPM'
      );

    const pulseRange =
      formatRange(
        mapping.minpulses,
        mapping.maxpulses
      );

    const intensityRange =
      formatRange(
        mapping.minintensity,
        mapping.maxintensity
      );

    return (
      `${mappingId}: ${valueRange}, ` +
      `${pulseRange} pulses, ` +
      `intensity ${intensityRange}, ` +
      `${assignedUsers} assigned ` +
      plural(
        assignedUsers,
        'user',
        'users'
      )
    );
  });

const bullets = [];

if (description) {
  bullets.push(
    `Purpose: ${description}`
  );
}

bullets.push(
  `Participants: ${assignedParticipants} assigned ` +
  plural(
    assignedParticipants,
    'participant',
    'participants'
  ) +
  '.'
);

if (totalReadings > 0) {
  bullets.push(
    `Recent data: ${totalReadings} readings from ` +
    `${participantsWithReadings} ` +
    plural(
      participantsWithReadings,
      'participant',
      'participants'
    ) +
    ` during the last ${periodDays} days; ` +
    `observed values ranged from ` +
    `${minimumValue} to ${maximumValue} BPM` +
    (
      averageValue !== null
        ? `, with an average of ${averageValue} BPM.`
        : '.'
    )
  );
} else {
  bullets.push(
    `Recent data: No sensor readings were found during the last ${periodDays} days.`
  );
}

if (mappingDescriptions.length > 0) {
  bullets.push(
    `Active mappings: ${mappingDescriptions.join('; ')}.`
  );
} else {
  bullets.push(
    'Active mappings: None were found.'
  );
}

bullets.push(
  `Recorded feedback activity: ${feedbackEvents} ` +
  plural(
    feedbackEvents,
    'event',
    'events'
  ) +
  ` involving ${participantsWithFeedback} ` +
  plural(
    participantsWithFeedback,
    'participant',
    'participants'
  ) +
  ` during the same period.`
);

const title =
  usecaseName
    ? `${usecaseName} experiment summary`
    : 'Experiment summary';

const reply =
  [
    title,
    '',
    ...bullets.map(
      bullet => `- ${bullet}`
    )
  ].join('\n');

const findings = [
  {
    finding_type:
      'experiment_population',

    summary:
      `${assignedParticipants} assigned participant(s); ` +
      `${participantsWithReadings} participant(s) with readings.`,

    confidence:
      'high',

    evidence_refs: [
      'public.User_UC_Mappings',
      'public.feedback_config_rules',
      'public.SensorData'
    ]
  },

  {
    finding_type:
      'sensor_coverage',

    summary:
      totalReadings > 0
        ? (
            `${totalReadings} readings during the last ` +
            `${periodDays} days, ranging from ` +
            `${minimumValue} to ${maximumValue}.`
          )
        : (
            `No readings were found during the last ` +
            `${periodDays} days.`
          ),

    confidence:
      'high',

    evidence_refs: [
      'public.SensorData'
    ]
  },

  {
    finding_type:
      'active_mapping_overview',

    summary:
      `${activeMappingCount} active mapping(s) were found.`,

    confidence:
      'high',

    evidence_refs: [
      'public.feedback_config_rules',
      'public.User_UC_Mappings'
    ]
  }
];

return [{
  json: {
    success:
      Boolean(usecaseName),

    reply,

    session_id:
  String(
    $('Normalize Participant Request')
      .first()
      .json
      .session_id ?? ''
  ),

    citations:
      [],

    warnings,

    proposals:
      [],

    recommended_actions:
      [],

    participant_assessment:
      null,

    findings
  }
}];
